-- DB_ID: technical primary key generated by the database (works on PostgreSQL and H2).
-- ID   : business id coming from the inbound message; NOT unique, so the same person
--        can be received several times (each reception is a new row).
CREATE TABLE IF NOT EXISTS PERSON (
    DB_ID       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID          BIGINT       NOT NULL,
    FIRST_NAME  VARCHAR(100) NOT NULL,
    LAST_NAME   VARCHAR(100) NOT NULL,
    EMAIL       VARCHAR(255),
    BIRTH_DATE  DATE,
    COUNTRY     VARCHAR(2),
    FULL_NAME   VARCHAR(201),
    AGE         INT,
    SOURCE      VARCHAR(100),
    CREATED_AT  TIMESTAMP    NOT NULL
);

-- Fast lookups by business id (not unique).
CREATE INDEX IF NOT EXISTS IDX_PERSON_ID ON PERSON (ID);
